<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($title??'') ?></title><link rel="stylesheet" href="<?= e(url('assets/css/app.css')) ?>"></head><body><header class="topbar"><a class="brand" href="<?= e(url()) ?>"><?= e($settings['site_title']??'E-pin') ?></a><form class="header-search" method="get" action="<?= e(url('search')) ?>" role="search"><input type="search" name="q" value="<?= e($searchTerm??'') ?>" minlength="2" maxlength="80" placeholder="Oyun, ürün veya kategori ara" aria-label="Ürün ara"><button type="submit">Ara</button></form><nav><?php foreach(($menus??[]) as $menu): ?><?php $href=preg_match('~^https?://~i',$menu['url'])?$menu['url']:url($menu['url']); ?><a href="<?= e($href) ?>"><?= e($menu['title']) ?></a><?php endforeach; ?><?php foreach(($categories??[]) as $c): ?><a href="<?= e(url('category/'.rawurlencode($c['slug']))) ?>"><?= e($c['name']) ?></a><?php endforeach; ?><a href="<?= e(url('cart')) ?>">Sepet (<?= array_sum($_SESSION['cart']??[]) ?>)</a><?php if(!empty($_SESSION['user'])): ?><?php if(($_SESSION['user']['role']??'')==='admin'): ?><a href="<?= e(url('admin')) ?>">Yönetim</a><?php elseif(($_SESSION['user']['role']??'')==='seller'): ?><a href="<?= e(url('seller')) ?>">Satıcı paneli</a><a href="<?= e(url('account')) ?>">Hesabım</a><?php else: ?><a href="<?= e(url('account')) ?>">Hesabım</a><?php if(config('business_mode')==='multi_vendor'): ?><a href="<?= e(url('seller/apply')) ?>">Satıcı ol</a><?php endif; ?><?php endif; ?><a href="<?= e(url('logout')) ?>">Çıkış</a><?php else: ?><a href="<?= e(url('login')) ?>">Giriş</a><?php endif; ?></nav></header><main class="container"><?php if($m=flash('error')): ?><div class="alert"><?= e($m) ?></div><?php endif; ?><?php if($m=flash('success')): ?><div class="success"><?= e($m) ?></div><?php endif; ?><?php require APP_ROOT.'/app/views/'.$view.'.php'; ?></main><footer class="footer"><?= e($settings['footer_text'